    static_assert(std::is_same_v<bigint::mod_t<B<false>, B<true, 0x1>>, B<false>>);
    static_assert(std::is_same_v<bigint::div_t<B<false>, B<false, 0xffffffff>>, B<false>>);
    static_assert(std::is_same_v<bigint::mod_t<B<false>, B<false, 0xffffffff>>, B<false>>);
