// these divisions take the rare add-back step of Knuth's algorithm D
TEST(bigint, div_add_back) {
    static_assert(std::is_same_v<bigint::div_t<B<false, 0x7fffffff, 0x0, 0x0, 0x80000000>, B<false, 0xfffffffe, 0x0, 0x7fffffff>>, B<false, 0x7fffffff>>);  // NOLINT(whitespace/line_length)
    static_assert(std::is_same_v<bigint::mod_t<B<false, 0x7fffffff, 0x0, 0x0, 0x80000000>, B<false, 0xfffffffe, 0x0, 0x7fffffff>>, B<false, 0xfffffffd, 0xc0000001, 0x7fffffff>>);  // NOLINT(whitespace/line_length)
    static_assert(std::is_same_v<bigint::div_t<B<true, 0x7fffffff, 0x0, 0x0, 0x80000000>, B<false, 0xfffffffe, 0x0, 0x7fffffff>>, B<true, 0x7fffffff>>);  // NOLINT(whitespace/line_length)
    static_assert(std::is_same_v<bigint::mod_t<B<true, 0x7fffffff, 0x0, 0x0, 0x80000000>, B<false, 0xfffffffe, 0x0, 0x7fffffff>>, B<true, 0xfffffffd, 0xc0000001, 0x7fffffff>>);  // NOLINT(whitespace/line_length)
    static_assert(std::is_same_v<bigint::div_t<B<false, 0x80000001, 0x0, 0xfffffffe, 0xfffffffe, 0x80000001>, B<false, 0x80000000, 0x0, 0xfffffffe>>, B<false, 0x1, 0x1, 0xffffffff>>);  // NOLINT(whitespace/line_length)
    static_assert(std::is_same_v<bigint::mod_t<B<false, 0x80000001, 0x0, 0xfffffffe, 0xfffffffe, 0x80000001>, B<false, 0x80000000, 0x0, 0xfffffffe>>, B<false, 0x7fffffff, 0x3, 0x7fffffff>>);  // NOLINT(whitespace/line_length)
    static_assert(std::is_same_v<bigint::div_t<B<true, 0x80000001, 0x0, 0xfffffffe, 0xfffffffe, 0x80000001>, B<false, 0x80000000, 0x0, 0xfffffffe>>, B<true, 0x1, 0x1, 0xffffffff>>);  // NOLINT(whitespace/line_length)
    static_assert(std::is_same_v<bigint::mod_t<B<true, 0x80000001, 0x0, 0xfffffffe, 0xfffffffe, 0x80000001>, B<false, 0x80000000, 0x0, 0xfffffffe>>, B<true, 0x7fffffff, 0x3, 0x7fffffff>>);  // NOLINT(whitespace/line_length)
    static_assert(std::is_same_v<bigint::div_t<B<false, 0xfffffffe, 0x80000001, 0x80000000, 0x1, 0xfffffffe>, B<false, 0xffffffff, 0x80000001, 0x7fffffff>>, B<false, 0xfffffffe, 0xffffffff>>);  // NOLINT(whitespace/line_length)
    static_assert(std::is_same_v<bigint::mod_t<B<false, 0xfffffffe, 0x80000001, 0x80000000, 0x1, 0xfffffffe>, B<false, 0xffffffff, 0x80000001, 0x7fffffff>>, B<false, 0x80000002, 0x2, 0x7ffffffd>>);  // NOLINT(whitespace/line_length)
    static_assert(std::is_same_v<bigint::div_t<B<true, 0xfffffffe, 0x80000001, 0x80000000, 0x1, 0xfffffffe>, B<false, 0xffffffff, 0x80000001, 0x7fffffff>>, B<true, 0xfffffffe, 0xffffffff>>);  // NOLINT(whitespace/line_length)
    static_assert(std::is_same_v<bigint::mod_t<B<true, 0xfffffffe, 0x80000001, 0x80000000, 0x1, 0xfffffffe>, B<false, 0xffffffff, 0x80000001, 0x7fffffff>>, B<true, 0x80000002, 0x2, 0x7ffffffd>>);  // NOLINT(whitespace/line_length)
}

