TEST(bigint, construction) {
    static_assert(std::is_same_v<bigint::inject_constant_t<0>, B<false>>);
    static_assert(std::is_same_v<bigint::inject_constant_t<1>, B<false, 0x1>>);
    static_assert(std::is_same_v<bigint::inject_constant_t<-1>, B<true, 0x1>>);
    static_assert(std::is_same_v<bigint::inject_constant_t<9223372036854775807LL>, B<false, 0x7fffffff, 0xffffffff>>);
    static_assert(std::is_same_v<bigint::inject_constant_t<INT64_MIN>, B<true, 0x80000000, 0x0>>);
    static_assert(std::is_same_v<bigint::inject_constant_t<4294967296LL>, B<false, 0x1, 0x0>>);
    static_assert(std::is_same_v<bigint::inject_constant_t<123456789>, B<false, 0x75bcd15>>);
    static_assert(std::is_same_v<bigint::from_hex_t<"0">, B<false>>);
    static_assert(std::is_same_v<bigint::from_string_t<"0">, B<false>>);
    static_assert(std::is_same_v<bigint::from_hex_t<"12A">, B<false, 0x12a>>);
    static_assert(std::is_same_v<bigint::from_string_t<"298">, B<false, 0x12a>>);
    static_assert(std::is_same_v<bigint::from_hex_t<"123ABF67EA">, B<false, 0x12, 0x3abf67ea>>);
    static_assert(std::is_same_v<bigint::from_string_t<"78295033834">, B<false, 0x12, 0x3abf67ea>>);
    static_assert(std::is_same_v<bigint::from_hex_t<"FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF">, B<false, 0xffffffff, 0xffffffff, 0xffffffff, 0xffffffff>>);  // NOLINT(whitespace/line_length)
    static_assert(std::is_same_v<bigint::from_string_t<"340282366920938463463374607431768211455">, B<false, 0xffffffff, 0xffffffff, 0xffffffff, 0xffffffff>>);  // NOLINT(whitespace/line_length)
    static_assert(std::is_same_v<bigint::from_hex_t<"D7D546601D330E37776EE1BD26A9D487CF6C3F40A1170DC4B1">, B<false, 0xd7, 0xd546601d, 0x330e3777, 0x6ee1bd26, 0xa9d487cf, 0x6c3f40a1, 0x170dc4b1>>);  // NOLINT(whitespace/line_length)
    static_assert(std::is_same_v<bigint::from_string_t<"1354806358539937863816163103165718895549103589060298740188337">, B<false, 0xd7, 0xd546601d, 0x330e3777, 0x6ee1bd26, 0xa9d487cf, 0x6c3f40a1, 0x170dc4b1>>);  // NOLINT(whitespace/line_length)
    static_assert(std::is_same_v<bigint::from_string_t<"-1267650600228229401496703205383">, B<true, 0x10, 0x0, 0x0, 0x7>>);  // NOLINT(whitespace/line_length)
    static_assert(std::is_same_v<bigint::from_hex_t<"-1F">, B<true, 0x1f>>);
}

TEST(bigint, to_string) {
    EXPECT_EQ((B<false>::to_string()), "0");
    EXPECT_EQ((B<true, 0x1>::to_string()), "-1");
    EXPECT_EQ((B<false, 0x10, 0x0, 0x0, 0x0>::to_string()), "1267650600228229401496703205376");
    EXPECT_EQ((B<true, 0x6f32f1ef, 0x8b18a2bc, 0x3cea5978, 0x9c79d441>::to_string()), "-147808829414345923316083210206383297601");  // NOLINT(whitespace/line_length)
    EXPECT_EQ((B<false, 0xffffffff, 0xffffffff, 0xffffffff, 0xffffffff>::to_hex()), "0XFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF");  // NOLINT(whitespace/line_length)
    EXPECT_EQ((B<true, 0xff>::to_hex()), "-0XFF");
}

TEST(bigint, get) {
    static_assert(B<false, 0x10, 0x0, 0x0, 0x0>::get<double>() == 0x1p100);
    static_assert(B<true, 0x1, 0x1>::get<double>() == -4294967297.0);
    static_assert(B<true, 0xc>::get<int64_t>() == -12);
}

TEST(bigint, is_an_euclidean_domain) {
    static_assert(aerobus::IsEuclideanDomain<bigint>);
    static_assert(!aerobus::IsField<bigint>);
    static_assert(bigint::zero::is_zero_v && !bigint::one::is_zero_v);
    static_assert(bigint::pos_v<bigint::one> && !bigint::pos_v<bigint::zero>);
}

TEST(bigint, coefficients_of_polynomials_and_fractions) {
    // (2^64 x + 1)^2 = 2^128 x^2 + 2^65 x + 1
    using PB = aerobus::polynomial<bigint>;
    using P = PB::val<B<false, 1, 0, 0>, bigint::one>;  // NOLINT(whitespace/line_length)
    static_assert(std::is_same_v<PB::mul_t<P, P>, PB::val<B<false, 0x1, 0x0, 0x0, 0x0, 0x0>, B<false, 0x2, 0x0, 0x0>, bigint::one>>);  // NOLINT(whitespace/line_length)
    // fractions of bigints: 1/3 + 1/6 = 1/2
    using QB = aerobus::FractionField<bigint>;
    using third = QB::val<bigint::one, bigint::inject_constant_t<3>>;
    using sixth = QB::val<bigint::one, bigint::inject_constant_t<6>>;
    static_assert(QB::eq_v<QB::add_t<third, sixth>, QB::val<bigint::one, bigint::inject_constant_t<2>>>);
    static_assert(QB::add_t<third, sixth>::get<double>() == 0.5);
}  // NOLINT(whitespace/line_length)
